package com.example.nailsalon.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity public class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull private Long clientId; @NotNull @Min(1) @Max(5) private int rating; @NotBlank @Size(max=1000) private String text; public Review(){} public Long getId(){return id;} public Long getClientId(){return clientId;} public void setClientId(Long v){clientId=v;} public int getRating(){return rating;} public void setRating(int v){rating=v;} public String getText(){return text;} public void setText(String v){text=v;} }
